import{_ as a,c as i,o,a5 as s}from"./chunks/framework.DuCYAsAJ.js";const k=JSON.parse('{"title":"YouTube Top-K 热门视频系统设计","description":"","frontmatter":{"title":"YouTube Top-K 热门视频系统设计","date":"2026-05-07T00:00:00.000Z","order":13},"headers":[],"relativePath":"posts/SystemDesign/topk.md","filePath":"posts/SystemDesign/topk.md","lastUpdated":1779463578000}'),d={name:"posts/SystemDesign/topk.md"};function t(l,e,h,c,n,r){return o(),i("div",null,[...e[0]||(e[0]=[s(`<h2 id="youtube-top-k-热门视频系统设计" tabindex="-1">YouTube Top-K 热门视频系统设计 <a class="header-anchor" href="#youtube-top-k-热门视频系统设计" aria-label="Permalink to &quot;YouTube Top-K 热门视频系统设计&quot;">​</a></h2><p>本文讨论的是一个 Top-K 系统，具体场景是 YouTube 视频观看量排行榜。系统需要在任意时刻返回 all-time 最热视频，以及最近 <code>1</code> 小时、<code>1</code> 天、<code>1</code> 月的 Top-K 视频</p><p>和普通排行榜设计的不同点在于：输入不是少量写入，而是一个巨大的 view event firehose。真正的难点也不在“如何排序”，而在于：如何定义时间窗口；如何在超高写入下维护计数；如何把查询延迟压到几十毫秒；以及是否需要近似算法来换取效率</p><h3 id="问题定义与边界" tabindex="-1">问题定义与边界 <a class="header-anchor" href="#问题定义与边界" aria-label="Permalink to &quot;问题定义与边界&quot;">​</a></h3><h4 id="功能需求" tabindex="-1">功能需求 <a class="header-anchor" href="#功能需求" aria-label="Permalink to &quot;功能需求&quot;">​</a></h4><p>客户端能够查询所有时间的 Top-K 视频；客户端能够查询最近 <code>1</code> 小时、<code>1</code> 天、<code>1</code> 月的 Top-K 视频；<code>K</code> 有上限，最多约 <code>1000</code></p><h4 id="非功能需求" tabindex="-1">非功能需求 <a class="header-anchor" href="#非功能需求" aria-label="Permalink to &quot;非功能需求&quot;">​</a></h4><ol><li>允许至多约 <code>1</code> 分钟统计延迟</li><li>查询结果默认要求精确，不先引入近似误差</li><li>查询延迟目标是 <code>10s of milliseconds</code></li><li>系统要能承受极大规模的视频观看事件流</li></ol><p>在设计这类系统时，最先要明确的是时间窗口的定义，是滑动窗口还是滚动窗口。为了让系统更容易做预计算，我们选择使用滚动窗口：最近 1 小时指上一个完整的小时，最近 1 天指上一个完整的天，最近 1 月指上一个完整的月</p><ul><li>本文暂不展开任意起止时间范围查询、任意大 <code>K</code>、个性化热门榜、复杂去重与反作弊</li></ul><h3 id="规模估算" tabindex="-1">规模估算 <a class="header-anchor" href="#规模估算" aria-label="Permalink to &quot;规模估算&quot;">​</a></h3><p>YouTube Shorts 约 <code>70B views/day</code>，折算后大约 <code>700k views/s</code>。视频规模约 <code>1</code> 小时内容 / 秒上传，如果平均每个视频约 <code>6</code> 分钟，那么约 <code>1M videos/day</code>，十年量级约 <code>3.6B videos</code></p><h3 id="核心实体、接口与数据模型" tabindex="-1">核心实体、接口与数据模型 <a class="header-anchor" href="#核心实体、接口与数据模型" aria-label="Permalink to &quot;核心实体、接口与数据模型&quot;">​</a></h3><h4 id="核心实体" tabindex="-1">核心实体 <a class="header-anchor" href="#核心实体" aria-label="Permalink to &quot;核心实体&quot;">​</a></h4><ul><li><code>Video</code></li><li><code>View</code></li><li><code>TimeWindow</code></li></ul><p>业务接口很简单，复杂度几乎都在内部数据流上</p><h4 id="初始接口" tabindex="-1">初始接口 <a class="header-anchor" href="#初始接口" aria-label="Permalink to &quot;初始接口&quot;">​</a></h4><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /views/top-k?window={WINDOW}&amp;k={K}</span></span></code></pre></div><p>返回结果可以是：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;videoId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;v1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;views&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123456</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;videoId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;v2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;views&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120001</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h4 id="输入数据流" tabindex="-1">输入数据流 <a class="header-anchor" href="#输入数据流" aria-label="Permalink to &quot;输入数据流&quot;">​</a></h4><p>假设系统上游已经有一个 <code>Kafka</code> 之类的 <code>ViewEvent</code> 流，Top-K 系统只需要消费这条流，并把它转成可查询的排行结果</p><h3 id="核心架构设计" tabindex="-1">核心架构设计 <a class="header-anchor" href="#核心架构设计" aria-label="Permalink to &quot;核心架构设计&quot;">​</a></h3><h4 id="一、先支持所有时间-top-k" tabindex="-1">一、先支持所有时间 Top-K <a class="header-anchor" href="#一、先支持所有时间-top-k" aria-label="Permalink to &quot;一、先支持所有时间 Top-K&quot;">​</a></h4><p><code>View Consumer</code> 从 Kafka 消费 <code>ViewEvent</code>；每来一个 view，就把对应 <code>videoId</code> 的计数加一；把计数落到一个数据库表；<code>TopK Service</code> 查询数据库中 <code>views</code> 最大的前 <code>K</code> 个视频</p><p>如果用关系型数据库表达，可以写成一张 <code>VideoViews(videoId, views)</code> 表，对 <code>views</code> 建索引。查询时大致就是：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> videoId, views</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> VideoViews</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> views </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DESC</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIMIT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> k;</span></span></code></pre></div><p>做完这步我们有输入事件流，有计数存储，有 Top-K 查询接口</p><h4 id="二、再支持时间窗口" tabindex="-1">二、再支持时间窗口 <a class="header-anchor" href="#二、再支持时间窗口" aria-label="Permalink to &quot;二、再支持时间窗口&quot;">​</a></h4><p>如果要支持时间窗口，我们可以不再只保存 <code>videoId -&gt; total views</code>，而是按时间粒度记录计数。例如按小时保存 <code>videoId</code>、<code>timestamp(hour bucket)</code>、<code>views</code>。这样查询最近 <code>1</code> 小时 / <code>1</code> 天 / <code>1</code> 月时，就可以扫描对应时间范围内的记录，按 <code>videoId</code> 做 <code>SUM</code>，再按和排序取 Top-K。这个设计的功能上没问题，但它会立刻暴露两个大瓶颈：每次查询都要扫很多数据；每次事件仍然要写库。这也是后续讨论的出发点</p><h3 id="深入讨论" tabindex="-1">深入讨论 <a class="header-anchor" href="#深入讨论" aria-label="Permalink to &quot;深入讨论&quot;">​</a></h3><h4 id="一、如何扩展读取-缓存和预计算" tabindex="-1">一、如何扩展读取：缓存和预计算 <a class="header-anchor" href="#一、如何扩展读取-缓存和预计算" aria-label="Permalink to &quot;一、如何扩展读取：缓存和预计算&quot;">​</a></h4><p>既然我们允许约 <code>1</code> 分钟延迟，那么最先应该想到的就是不要每次查询都现算</p><h5 id="_1-缓存查询结果" tabindex="-1">1. 缓存查询结果 <a class="header-anchor" href="#_1-缓存查询结果" aria-label="Permalink to &quot;1. 缓存查询结果&quot;">​</a></h5><p>最直接的优化是给 <code>TopK Service</code> 前面加缓存，key 为 <code>top-k:{window}:{truncated_timestamp}</code>，value 为该窗口的 Top-K 结果。这样大部分请求都能在亚毫秒级缓存里命中。但仅靠缓存仍有问题：缓存过期瞬间会有一波请求直接打回数据库，这些 miss 请求很可能同时突破 SLA</p><h5 id="_2-定时预计算并回填缓存" tabindex="-1">2. 定时预计算并回填缓存 <a class="header-anchor" href="#_2-定时预计算并回填缓存" aria-label="Permalink to &quot;2. 定时预计算并回填缓存&quot;">​</a></h5><p>既然结果天然按窗口更新，那么系统完全可以用 cron / scheduler 定时触发，预先把各窗口的 Top-K 结果算出来，直接回填到 Redis / Memcached。这样在线查询几乎只读缓存，不碰底层存储。这一步其实奠定了整个系统的读路径原则：查询层要尽量只服务预计算结果</p><h4 id="二、如何扩展写入-分片和批处理" tabindex="-1">二、如何扩展写入：分片和批处理 <a class="header-anchor" href="#二、如何扩展写入-分片和批处理" aria-label="Permalink to &quot;二、如何扩展写入：分片和批处理&quot;">​</a></h4><p>真正麻烦的是写入。按前面的估算流量约 <code>700k views/s</code>，如果每一条都触发一次数据库写入，单机关系型数据库很快就会被压垮</p><h5 id="_1-按-videoid-分片" tabindex="-1">1. 按 <code>videoId</code> 分片 <a class="header-anchor" href="#_1-按-videoid-分片" aria-label="Permalink to &quot;1. 按 \`videoId\` 分片&quot;">​</a></h5><p>因为上游 Kafka 天然支持按 <code>videoId</code> 分区，所以很自然的做法是 <code>ViewEvent</code> topic 按 <code>videoId</code> 分区，<code>View Consumer</code> 水平扩展，数据库也按相同规则分片。这样同一个视频的计数稳定落到同一 shard，中间不会产生复杂的跨分片写冲突。但仅靠分片还不够，如果想把每个分片的写入压到约 <code>10k tps</code>，可能仍然需要几十个数据库实例</p><h5 id="_2-批处理聚合" tabindex="-1">2. 批处理聚合 <a class="header-anchor" href="#_2-批处理聚合" aria-label="Permalink to &quot;2. 批处理聚合&quot;">​</a></h5><p>更好的方案是不要为每一次 view 单独写库，先在流处理层做批量聚合，再把聚合结果批量刷库。可以利用 Flink 实现这一模式：从 Kafka 消费事件，按 videoId 聚合，利用其 watermark 机制处理晚到事件，以小时为粒度输出每个视频的增量观看计数，最后将批量结果写入存储。这样做能显著降低写入频率，充分发挥数据库对批量写入的吞吐优势，同时还能顺便解决晚到事件的问题</p><h4 id="三、如何优化窗口查询" tabindex="-1">三、如何优化窗口查询 <a class="header-anchor" href="#三、如何优化窗口查询" aria-label="Permalink to &quot;三、如何优化窗口查询&quot;">​</a></h4><p>即使读层已经有缓存，系统仍然需要去把缓存算出来。而 naive 窗口查询本身仍然很重：例如查“最近一个月 Top-K”，需要扫描整个窗口内大量分桶数据，还要对每个视频聚合求和，这在大数据量下会非常慢</p><h5 id="_1-更粗粒度聚合" tabindex="-1">1. 更粗粒度聚合 <a class="header-anchor" href="#_1-更粗粒度聚合" aria-label="Permalink to &quot;1. 更粗粒度聚合&quot;">​</a></h5><p>一种改进是维护多个粒度：小时级、天级、月级。查询最近一个月时，就尽量用天级聚合，而不是把 <code>24 * 30</code> 个小时桶都重新加一遍。这能减少查询处理量，但系统仍然在“读时做很多聚合”</p><h5 id="_2-直接维护每个窗口的总表" tabindex="-1">2. 直接维护每个窗口的总表 <a class="header-anchor" href="#_2-直接维护每个窗口的总表" aria-label="Permalink to &quot;2. 直接维护每个窗口的总表&quot;">​</a></h5><p>直接维护 <code>VideoViewsLastHour</code>、<code>VideoViewsLastDay</code>、<code>VideoViewsLastMonth</code>、<code>VideoViewsAllTime</code> 这几张表。每张表都表示当前这个窗口内每个视频的总 views，然后对每张表的 <code>views</code> 列建立索引。这样查询时就变成了直接对对应窗口表做 <code>ORDER BY views DESC LIMIT k</code>，读路径几乎不再做聚合，而是直接读已经维护好的窗口状态。代价也很明确：写路径更复杂，每批聚合结果可能要写多张表</p><h4 id="四、如果是滑动窗口怎么办" tabindex="-1">四、如果是滑动窗口怎么办 <a class="header-anchor" href="#四、如果是滑动窗口怎么办" aria-label="Permalink to &quot;四、如果是滑动窗口怎么办&quot;">​</a></h4><p>我们前面主动选择了滚动窗口，因为它更容易预计算。但如果改变成滑动窗口，例如当前 <code>10:06</code> 查最近 1 小时，实际想看的是 <code>9:06 ~ 10:06</code>，那系统就要进一步演进</p><p>一种思路是 minute-grain 增量维护：每分钟聚合一次每个视频的 views 增量；对 <code>VideoViewsLastHour</code> 来说，加上当前这一分钟的增量，减去正好 <code>60</code> 分钟前那一分钟的增量。也就是说，窗口值不再通过扫描重算，而是 <code>current = current + increment - decrement</code></p><p>但这种做法复杂度和存储都会明显上升：必须保留细粒度历史桶用于 decrement，写路径变成读+写+更新。因此我们通常采用最近 1 小时支持滑动窗口，最近 1 天 / 1 月继续使用滚动窗口</p><h4 id="五、如果允许近似" tabindex="-1">五、如果允许近似 <a class="header-anchor" href="#五、如果允许近似" aria-label="Permalink to &quot;五、如果允许近似&quot;">​</a></h4><p>如果产品不要求绝对精确，而只关心趋势榜，那就可以继续演进到近似算法。官网题解重点提到 <code>Count-Min Sketch</code>，它适合在超大规模流里近似估计每个 item 的出现次数，同时显著降低内存占用。但 CMS 有一个限制：它天然支持 <code>add</code> 和 <code>estimate</code>，不直接保留完整 item 列表。因此 Top-K 场景通常需要 <code>Count-Min Sketch</code> 再配一个 heap / sorted set 保存候选 Top-K</p><p>事件到来时，先 <code>CMS.add(videoId)</code>；再 <code>CMS.estimate(videoId)</code>；用这个估计值去更新 heap / sorted set后持续裁剪，只保留前 <code>1000</code> 候选。这样可以显著减少状态体积，但代价是结果不再绝对精确</p><h4 id="六、为什么时序数据库不是最合适的" tabindex="-1">六、为什么时序数据库不是最合适的 <a class="header-anchor" href="#六、为什么时序数据库不是最合适的" aria-label="Permalink to &quot;六、为什么时序数据库不是最合适的&quot;">​</a></h4><p>很多人一看到“按小时 / 按天 / 按月统计”，就会想到时序数据库。但这里的问题不是“查询某个视频的一条时序曲线”，而是要跨所有 videoId 做全局 Top-K。这意味着系统可能面对几十亿的超高基数 videoId。而多数时序数据库更擅长处理某个指标的时间序列和较窄的 point/range 查询，并不天然适合跨数十亿键做全局 top 排名</p><h3 id="整体链路" tabindex="-1">整体链路 <a class="header-anchor" href="#整体链路" aria-label="Permalink to &quot;整体链路&quot;">​</a></h3><h4 id="写路径" tabindex="-1">写路径 <a class="header-anchor" href="#写路径" aria-label="Permalink to &quot;写路径&quot;">​</a></h4><ol><li>上游把 view 事件写入 Kafka</li><li>Flink 消费 Kafka</li><li>按 <code>videoId</code> 聚合，处理晚到事件</li><li>以小时或分钟粒度产出批量增量</li><li>批量更新各窗口总表</li></ol><h4 id="预计算路径" tabindex="-1">预计算路径 <a class="header-anchor" href="#预计算路径" aria-label="Permalink to &quot;预计算路径&quot;">​</a></h4><ol><li>定时任务按窗口读取各 shard 的 Top-K</li><li>在聚合层合并 shard 结果</li><li>把最终 Top-K 结果写入缓存</li></ol><h4 id="查询路径" tabindex="-1">查询路径 <a class="header-anchor" href="#查询路径" aria-label="Permalink to &quot;查询路径&quot;">​</a></h4><ol><li>客户端请求 <code>GET /views/top-k?window={WINDOW}&amp;k={K}</code></li><li><code>TopK Service</code> 直接命中缓存</li><li>返回结果</li></ol><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li><a href="https://www.hellointerview.com/learn/system-design/problem-breakdowns/top-k" target="_blank" rel="noreferrer">Hello Interview 官方讲解：YouTube Top K</a></li></ul>`,67)])])}const u=a(d,[["render",t]]);export{k as __pageData,u as default};
